xml.Script:
        Colors[0] := 'DD0000'; // Red
        Colors[1] := '22CC00'; // LightGreen
        Colors[2] := '0000EE'; // Blue
        Colors[3] := 'FF6000'; // Orange
        Colors[4] := '009600'; // Green
        Colors[5] := '0077EE'; // LightBlue
        Colors[6] := 'FFEE00'; // Yellow
        Colors[7] := 'FFFFFF'; // White

        R := 0.6;

        H := R * 0.75;
        sAngle := 2*Pi / 6;

        for i := 0 to 5 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
        end;

        for i := 0 to 2 do begin
            ax[i] := sin(sAngle * (2 * i + 0.5));
            ay[i] := cos(sAngle * (2 * i + 0.5));
        end;

        D1 := R * sqrt(3) / 4;
        D2 := H / 3;
